"""AI visuals: one precise image prompt per sentence, generated by a FREE image model, with fallbacks.

Providers, tried in order (all free, no paid keys):
  1. FLUX.1-schnell on the official Hugging Face Space (ZeroGPU). Works anonymously; HF_TOKEN (free account)
     raises the daily GPU quota. Uses gradio_client (small, pure-Python).
  2. Hugging Face Inference API FLUX.1-schnell (only if HF_TOKEN has the "Inference Providers" permission).
  3. Pollinations.ai classic endpoint (free, no key; lower quality, rate-limited).
Images are cached on disk by (prompt, seed, size). Gemini image generation is NOT used: the free tier has no
image quota (returns 429 "limit 0").
"""
import hashlib, json, os, re, threading, time, urllib.parse, urllib.request
from pathlib import Path

CACHE = Path(os.environ.get("DIRECTOR_CACHE", "/tmp/director_cache")) / "ai"
CACHE.mkdir(parents=True, exist_ok=True)
_LOCK = threading.Lock()  # one generation at a time: polite to free services, low RAM
_STATE = {"space_fail_until": 0.0, "hf_fail_until": 0.0, "last": ""}

STYLES = {
    "realistic": "cinematic photograph, shot on 35mm film, natural skin tones, realistic lighting, shallow depth of field, "
                 "high detail, documentary style, no text, no watermark",
    "pixar": "3D animated film still, Pixar-style character design, soft global illumination, vibrant warm colours, "
             "stylised but expressive faces, rendered in high detail, no text, no watermark",
    "stick": "simple hand-drawn stick figure doodle, thick black marker lines, round head with minimal dot eyes and expressive "
             "pose, whiteboard explainer style, clean flat off-white paper background, very few simple props in line art, "
             "one small accent colour at most, lots of empty space, no shading, no text, no watermark",
}
STYLE_NAMES = {"realistic": "photorealistic cinematic documentary", "pixar": "3D Pixar-style animated film",
               "stick": "minimal hand-drawn stick-figure whiteboard explainer (storytime-channel doodle); the recurring "
                        "character is the same stick figure every scene with one identifying detail (e.g. a cap or tie)"}


def norm_style(v):
    return v if v in STYLES else "realistic"


NEGATIVE = "text, captions, letters, logos, watermark, signature, split panels, extra limbs, extra fingers, deformed hands, distorted faces, blurry, low quality"
MODELS = {"image": "Nano Banana Pro", "video": "Veo 3.1 - Lite", "video_alt": "Omni Flash"}  # Google Flow picker names


def _assemble(sc, bible, style, aspect, target):
    tok = STYLES.get(style, STYLES["realistic"])
    parts = [sc.get("subject_action", ""), sc.get("setting", ""), sc.get("camera", ""), sc.get("lighting_mood", "")]
    if bible:
        parts.append(f"Story bible: {bible}")
    if target == "video":
        parts.append(f"Motion: {sc.get('motion') or 'subtle natural movement'}; camera {sc.get('camera_move') or 'slow push-in'}; 8 seconds")
    parts += [tok, f"aspect ratio {aspect}", f"Avoid: {NEGATIVE}"]
    return ". ".join(re.sub(r"\s+", " ", str(x)).strip(" .") for x in parts if x)[:1400]


def prompts(lines, topic, style, gem, aspect="9:16", target="image"):
    """Director-grade prompts: a story bible (recurring cast, wardrobe, location, palette) + one structured,
    model-specific prompt per sentence that literally depicts it. Returns (prompts, meta)."""
    d = gem(f"""You are the director and art director of a {'vertical 9:16' if aspect == '9:16' else 'widescreen 16:9'} short video about: {topic}.
Style: {STYLE_NAMES.get(style, STYLE_NAMES['realistic'])}. Target model: {'Google Veo (video clips, 8 s)' if target == 'video' else 'text-to-image model'}.
First write a STORY BIBLE used in every scene for consistency: recurring character(s) with age, look, wardrobe; main location; era; props; colour palette.
Then for EACH numbered narration line write a scene that LITERALLY depicts what the line says (accuracy first: the exact subject, number, place, action).
- If the topic or line concerns Nigeria / Lagos / Africa, show that place and Black Nigerian people explicitly (yellow danfo buses, okada, Third Mainland Bridge, Lagos markets, Nigerian clothing). Never generic Western cities.
- Abstract lines (statistics, feelings, calls to action): pick one concrete, visual metaphor in the same world.
- No readable text or signs. One clear focal point. Vary shot types across scenes.
Lines:
""" + "\n".join(f"{i+1}. {l}" for i, l in enumerate(lines)) + """
Return JSON {"bible": "60-90 words", "cast": "...", "world": "...", "scenes": [{"subject_action": "...", "setting": "place, era, props",
"camera": "shot type, angle, lens", "lighting_mood": "lighting, mood, colour", "motion": "what moves (for video)", "camera_move": "dolly/pan/etc"}]}
with exactly one scene per line.""", temp=0.5)
    scs = [x if isinstance(x, dict) else {"subject_action": str(x)} for x in (d.get("scenes") or [])][:len(lines)]
    while len(scs) < len(lines):
        scs.append({"subject_action": lines[len(scs)]})
    bible = re.sub(r"\s+", " ", str(d.get("bible", "")))[:600]
    out = [_assemble(sc, bible, style, aspect, target) for sc in scs]
    return out, {"cast": str(d.get("cast", ""))[:200], "world": str(d.get("world", ""))[:200], "bible": bible, "scenes": scs}


def verify(img_bytes, line, prompt, gem):
    """Gemini vision: does the image literally show the line? Returns (score 0-10, critique, better_prompt)."""
    try:
        d = gem(f"""Narration line: "{line}"\nImage prompt used: {prompt[:900]}\n
Score 0-10 how accurately and clearly this image depicts the narration line for a viewer (subject, action, place, people, no artefacts or text).
If below 7, explain what is wrong and rewrite the prompt to fix it (keep the story bible and style parts).
Return JSON {{"score": n, "critique": "...", "prompt": "rewritten prompt or empty"}}""", images=[("image", img_bytes)], temp=0.2)
        return float(d.get("score", 0)), str(d.get("critique", ""))[:300], str(d.get("prompt", ""))[:1400]
    except Exception as e:
        return -1.0, f"verify failed {type(e).__name__}", ""


def generate_verified(prompt, line, w, h, seed, gem, log=print, retries=2):
    """Generate, score with vision, rewrite + regenerate below 7 (max `retries`). Returns best (path, prov, prompt, score, tries)."""
    best, tries = None, []
    for k in range(retries + 1):
        path, prov = generate(prompt, w, h, seed + k * 101, log=log)
        jpg = _jpeg(path)
        sc, crit, better = verify(jpg, line, prompt, gem)
        tries.append({"prompt": prompt, "score": sc, "model": prov, "critique": crit})
        log(f"director: scene score {sc}/10 via {prov}" + (f" ({crit[:80]})" if sc < 7 else ""))
        if not best or sc > best[3]:
            best = (path, prov, prompt, sc)
        if sc >= 7 or sc < 0 or not better:
            break
        prompt = better
    return (*best, tries)


def _jpeg(path):
    import subprocess
    r = subprocess.run(["ffmpeg", "-loglevel", "error", "-i", str(path), "-vf", "scale=384:-2", "-frames:v", "1", "-f", "image2", "-c:v", "mjpeg", "-"],
                       capture_output=True, timeout=60)
    return r.stdout


def seed_for(topic):
    return int(hashlib.md5((topic or "x").encode()).hexdigest()[:6], 16) % 1_000_000


def _space(prompt, w, h, seed):
    from gradio_client import Client
    tok = os.environ.get("HF_TOKEN") or None
    try:
        c = Client("black-forest-labs/FLUX.1-schnell", token=tok, verbose=False)
    except TypeError:  # older gradio_client
        c = Client("black-forest-labs/FLUX.1-schnell", hf_token=tok, verbose=False)
    r = c.predict(prompt=prompt, seed=seed, randomize_seed=False, width=w, height=h, num_inference_steps=4, api_name="/infer")
    return Path(r[0] if isinstance(r, (list, tuple)) else r).read_bytes()


def _hf_api(prompt, w, h, seed):
    tok = os.environ.get("HF_TOKEN", "")
    if not tok:
        raise RuntimeError("no HF_TOKEN")
    req = urllib.request.Request("https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-schnell",
                                 data=json.dumps({"inputs": prompt, "parameters": {"width": w, "height": h, "seed": seed}}).encode(),
                                 headers={"Authorization": f"Bearer {tok}", "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=120) as r:
        b = r.read()
    if not b[:4] in (b"\xff\xd8\xff\xe0", b"\xff\xd8\xff\xe1", b"\x89PNG") and b[:3] != b"\xff\xd8\xff":
        raise RuntimeError("not an image")
    return b


def _pollinations(prompt, w, h, seed):
    url = ("https://image.pollinations.ai/prompt/" + urllib.parse.quote(prompt[:900]) + "?" +
           urllib.parse.urlencode({"width": w, "height": h, "seed": seed, "nologo": "true", "model": "flux"}))
    for i in range(3):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "MoneyPrinterStudio/1.0"}), timeout=120) as r:
                b = r.read()
            if b[:3] == b"\xff\xd8\xff" or b[:4] == b"\x89PNG" or b[:4] == b"RIFF":
                return b
        except Exception:
            pass
        time.sleep(11 * (i + 1))  # classic API asks for a 10s back-off
    raise RuntimeError("pollinations unavailable")


def generate(prompt, w, h, seed, log=print):
    """Return (path_to_jpg, provider). Raises if every free provider fails."""
    prompt = prompt.split(". Avoid:")[0]  # FLUX has no negative prompt; naming 'text' can summon text
    key = hashlib.md5(f"{prompt}|{seed}|{w}x{h}".encode()).hexdigest()
    out = CACHE / f"{key}.jpg"
    if out.exists():
        return str(out), "cache"
    errs = []
    with _LOCK:
        now = time.time()
        chain = []
        if now > _STATE["space_fail_until"]:
            chain.append(("FLUX.1-schnell (HF Space)", _space, "space_fail_until"))
        if os.environ.get("HF_TOKEN") and now > _STATE["hf_fail_until"]:
            chain.append(("FLUX.1-schnell (HF Inference)", _hf_api, "hf_fail_until"))
        chain.append(("Pollinations", _pollinations, None))
        for name, fn, flag in chain:
            try:
                b = fn(prompt, w, h, seed)
                from PIL import Image
                import io
                Image.open(io.BytesIO(b)).convert("RGB").save(out, "JPEG", quality=90)
                _STATE["last"] = name
                if errs:
                    print("ai visuals fallback:", " | ".join(errs)[:300], flush=True)
                return str(out), name
            except Exception as e:
                msg = str(e)[:160]
                errs.append(f"{name}: {type(e).__name__} {msg}")
                if flag:  # quota / outage: skip this provider for 10 minutes
                    _STATE[flag] = time.time() + (3600 if re.search(r"ZeroGPU quota", msg) else 600 if re.search(r"quota|limit|403|401|429|exceeded", msg, re.I) else 60)
    log("ai visuals failed: " + " | ".join(errs)[:400])
    raise RuntimeError("no free image provider available")


def status():
    return {"provider": _STATE["last"] or "FLUX.1-schnell (HF Space)", "hf_token": bool(os.environ.get("HF_TOKEN"))}
